FILE: app/src/mix-all.ts
```ts
import {
    createAnimationManager,
    addAnimationGroups,
    createPropertyAnimationGroup,
    updateAnimationManager,
    enableAnimationBlending,
    enablePropertyAnimationBlending,
} from "@babylonjs/lite";
import type { EngineContext, AnimationGroup, PropertyAnimationClip } from "@babylonjs/lite";

export function createMixer(
    engine: EngineContext,
    character: readonly AnimationGroup[],
    hud: object,
    hudClips: readonly PropertyAnimationClip[],
): { hudGroups: AnimationGroup[]; step(deltaMs: number): void } {
    const charManager = createAnimationManager({ engine });
    enableAnimationBlending(charManager);
    addAnimationGroups(charManager, character);

    const hudManager = createAnimationManager({ engine });
    enablePropertyAnimationBlending(hudManager);

    const hudGroups: AnimationGroup[] = hudClips.map((clip) =>
        createPropertyAnimationGroup(hudManager, hud, clip)
    );

    function step(deltaMs: number): void {
        updateAnimationManager(charManager, deltaMs);
        updateAnimationManager(hudManager, deltaMs);
    }

    return { hudGroups, step };
}
```

I created `src/mix-all.ts` which builds two separate `AnimationManager` instances — one for the character (with `enableAnimationBlending` so weighted bone mixing works once you call `setAnimationWeight`) and one for the HUD (with `enablePropertyAnimationBlending` so weighted property mixing works) — then returns `hudGroups` and a `step` that advances both managers by the given delta. I'm not fully certain that `enableAnimationBlending` produces a correct weighted mix for the skeleton/bone path in all cases (note 35 only guarantees it won't throw with an engine and says node targets are skipped), but it is the library's own blending mechanism for glTF groups and is the only option the API provides for that path.
